import{_ as a,o as s,c as t,ag as i}from"./chunks/framework.CPvOxTBX.js";const k=JSON.parse('{"title":"云同步","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/cloud-sync.md","filePath":"zh/guide/cloud-sync.md","lastUpdated":1792239626000}'),n={name:"zh/guide/cloud-sync.md"};function d(o,e,l,p,h,c){return s(),t("div",null,e[0]||(e[0]=[i('<h1 id="云同步" tabindex="-1">云同步 <a class="header-anchor" href="#云同步" aria-label="Permalink to &quot;云同步&quot;">​</a></h1><p>词悦可以通过远程文件存储合并你的单词本、标签、抽认卡和复习历史。首次连接时会显示只读预览，在你确认之前不会写入任何内容。词典单独列出，只有当你选中时才会传输。</p><p>凭据保存在平台的安全存储中，而不是应用偏好设置里。词悦不提供自建的同步服务。WebDAV、SFTP 和 S3 兼容存储使用的都是开放协议，不需要注册词悦账号。</p><h2 id="webdav" tabindex="-1">WebDAV <a class="header-anchor" href="#webdav" aria-label="Permalink to &quot;WebDAV&quot;">​</a></h2><p>输入服务器 URL、远程文件夹，以及可选的用户名/密码。只要服务器不在本机，就请使用 HTTPS。WebDAV 适用于 Nextcloud、ownCloud 以及提供 WebDAV 的 NAS 等服务。</p><h2 id="sftp" tabindex="-1">SFTP <a class="header-anchor" href="#sftp" aria-label="Permalink to &quot;SFTP&quot;">​</a></h2><p>输入 <code>sftp://</code> 格式的 URL，例如 <code>sftp://nas.example.net:22/backups</code>。URL 中的路径是基准目录；省略时使用 SFTP 账号的主目录。输入用户名，以及密码、SSH 私钥文件或两者都填。加密的私钥可以用 passphrase 解锁。</p><p>词悦要求固定 SSH 主机密钥指纹，缺失或不符的指纹会被拒绝。请通过可信渠道从服务器管理员处获取 SHA-256 指纹。对于 OpenSSH 服务器，可以用下面的命令打印指纹，再与管理员给的值比对：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh-keyscan</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ed25519</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nas.example.net</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ssh-keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -lf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span></code></pre></div><p>把 <code>SHA256:...</code> 的值填进词悦。<code>ssh-keyscan</code> 本身不验证服务器身份，所以它的输出必须经过独立核实才能信任。如果服务器用的是其他主机密钥算法，请指定对应的算法。主机密钥变更后（比如更换服务器），需要更新保存的指纹。</p><h2 id="s3-兼容存储" tabindex="-1">S3 兼容存储 <a class="header-anchor" href="#s3-兼容存储" aria-label="Permalink to &quot;S3 兼容存储&quot;">​</a></h2><p>输入 HTTPS endpoint、bucket、region、access key ID 和 secret access key。远程文件夹会作为 bucket 内的前缀使用，词悦只列出该前缀下的对象，不会扫描无关内容。例如：</p><ul><li>MinIO：使用服务器的 endpoint 和 region，通常启用 path-style addressing。</li><li>Cloudflare R2：使用账号的 endpoint，region 填 <code>auto</code>，通常关闭 path-style addressing。</li><li>AWS S3：使用 <code>https://s3.&lt;region&gt;.amazonaws.com</code>、对应的 region，关闭 path-style addressing。</li></ul><p>寻址模式取决于服务商；如果连接测试失败，请检查服务商的 endpoint 和 bucket 寻址要求。明文 HTTP 只接受回环开发地址，如 <code>http://127.0.0.1:9000</code>。请使用仅限该 bucket、最小权限（列出、读取、写入、复制、删除词悦同步对象）的凭据。</p><h2 id="同步行为" tabindex="-1">同步行为 <a class="header-anchor" href="#同步行为" aria-label="Permalink to &quot;同步行为&quot;">​</a></h2><p>词悦保存带版本的同步记录，合并各设备的变更。并发的编辑和删除会被保留为冲突，而不是悄悄覆盖。预览不会创建目录、上传数据，也不会修改远程存储。确认预览后才开始同步。</p><p>词典文件默认不包含在内。请在预览中逐个选中需要同步的词典。下载的文件会先校验再加入本地词典库，不会自动启用。</p>',17)]))}const u=a(n,[["render",d]]);export{k as __pageData,u as default};
